def hesapla_kultur_norm(ders_yuku):
    if ders_yuku < 6:
        return 0
    elif 6 <= ders_yuku <= 30:
        return 1
    elif 31 <= ders_yuku <= 42:
        return 2
    else:
        kalan = ders_yuku - 42
        ek_norm = kalan // 21
        artik = kalan % 21
        toplam = 2 + ek_norm
        if artik >= 15:
            toplam += 1
        return toplam
